[{"order":1,"type":"heading","text":"Secure Local Storage: Room Database, Migrations, and SQLCipher Encryption in Android"},{"order":2,"type":"paragraph","text":"When building secure Android applications, protecting sensitive user data at rest is paramount. By default, Android SQLite databases are unencrypted and stored in the application's private sandbox. If a device is rooted, attackers can easily extract and read this data. Integrating SQLCipher with Android Room provides robust, transparent 256-bit AES encryption. This tutorial covers setting up a Room database, implementing secure encryption via SQLCipher, and handling schema updates using migrations."},{"order":3,"type":"subheading","text":"1. Dependencies Setup"},{"order":4,"type":"paragraph","text":"To implement Room with SQLCipher encryption, you need the standard Room libraries alongside the SQLCipher for Android dependency. Update your module-level build.gradle.kts file with the following dependencies:"},{"order":5,"type":"code","text":"implementation("androidx.room:room-runtime:2.6.1")
implementation("androidx.room:room-ktx:2.6.1")
ksp("androidx.room:room-compiler:2.6.1")
implementation("net.zetetic:android-database-sqlcipher:4.5.4")
implementation("androidx.sqlite:sqlite:2.4.0")"},{"order":6,"type":"subheading","text":"2. Creating the Room Entity and DAO"},{"order":7,"type":"paragraph","text":"Define a simple data entity representing a secure user note, followed by a Data Access Object (DAO) to interact with the database."},{"order":8,"type":"code","text":"@Entity(tableName = "secure_notes")
data class SecureNoteEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val title: String,
    val content: String
)

@Dao
interface SecureNoteDao {
    @Query("SELECT * FROM secure_notes")
    fun getAllNotes(): Flow<List<SecureNoteEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertNote(note: SecureNoteEntity)
}"},{"order":9,"type":"subheading","text":"3. Configuring SQLCipher Encryption"},{"order":10,"type":"paragraph","text":"To encrypt the Room database, you must supply a custom SupportSQLiteOpenHelper.Factory using SQLCipher. The passphrase should ideally be retrieved securely from the Android Keystore system rather than hardcoded."},{"order":11,"type":"code","text":"@Database(entities = [SecureNoteEntity::class], version = 1, exportSchema = true)
abstract class AppDatabase : RoomDatabase() {
    abstract fun secureNoteDao(): SecureNoteDao

    companion5 object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getDatabase(context: Context, passphrase: ByteArray): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val factory = SupportFactory(passphrase)
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "secure_app_database.db"
                )
                .openHelperFactory(factory)
                .build()
                INSTANCE = instance
                instance
            }
        }
    }
}"},{"order":12,"type":"subheading","text":"4. Implementing Database Migrations"},{"order":13,"type":"paragraph","text":"As your application evolves, schema changes are inevitable. When using encrypted databases with Room, migrations are executed identically to standard databases, but SQLCipher ensures the updated database file remains fully encrypted. Below is an example migration from version 1 to version 2, adding a timestamp column."},{"order":14,"type":"code","text":"val MIGRATION_1_2 = object : Migration(1, 2) {
    override fun migrate(database: SupportSQLiteDatabase) {
        database.execSQL("ALTER TABLE secure_notes ADD COLUMN createdAt INTEGER NOT NULL DEFAULT 0")
    }
}

// Update database builder implementation to include migration:
val instance = Room.databaseBuilder(
    context.applicationContext,
    AppDatabase::class.java,
    "secure_app_database.db"
)
.openHelperFactory(factory)
.addMigrations(MIGRATION_1_2)
.build()"},{"order":15,"type":"subheading","text":"Best Practices for Encryption Keys"},{"order":16,"type":"bullet_point","text":"Never hardcode your database passphrase in plain text inside your source code."},{"order":17,"type":"bullet_point","text":"Use the Android KeyStore provider to encrypt and safely store the database passphrase locally."},{"order":18,"type":"bullet_point","text":"Always test your Room migrations thoroughly using MigrationTestHelper to prevent runtime crashes during updates."}]
